DO $$
DECLARE
    source_count INTEGER;
    district_count INTEGER;
BEGIN
    SELECT COUNT(DISTINCT code) INTO source_count FROM _legacy_district_boundary_source;
    SELECT COUNT(*) INTO district_count
    FROM districts d
    JOIN (SELECT DISTINCT code FROM _legacy_district_boundary_source) s USING (code);
    IF source_count <> 22 OR district_count <> 22 THEN
        RAISE EXCEPTION 'legacy district mapping incomplete: source=%, districts=%', source_count, district_count;
    END IF;
END $$;

DO $$
DECLARE
    valid_count INTEGER;
    overlap_count INTEGER;
BEGIN
    WITH parsed AS (
        SELECT code, ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(geometry::text), 4326)) AS geom
        FROM _legacy_district_boundary_source
    ), merged AS (
        SELECT code, ST_UnaryUnion(ST_Collect(geom)) AS geom
        FROM parsed
        GROUP BY code
    )
    SELECT COUNT(*) INTO valid_count
    FROM merged
    WHERE ST_IsValid(geom)
      AND GeometryType(geom) = 'POLYGON'
      AND ST_Area(geom::geography) > 1000000;

    WITH parsed AS (
        SELECT code, ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(geometry::text), 4326)) AS geom
        FROM _legacy_district_boundary_source
    ), merged AS (
        SELECT code, ST_UnaryUnion(ST_Collect(geom)) AS geom
        FROM parsed
        GROUP BY code
    )
    SELECT COUNT(*) INTO overlap_count
    FROM merged a
    JOIN merged b ON a.code < b.code
    WHERE ST_Area(ST_Intersection(a.geom, b.geom)::geography) > 1;

    IF valid_count <> 22 OR overlap_count <> 0 THEN
        RAISE EXCEPTION 'legacy source geometry invalid: valid=%/22, overlaps=%', valid_count, overlap_count;
    END IF;
END $$;

WITH parsed AS (
    SELECT code, ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(geometry::text), 4326)) AS geom
    FROM _legacy_district_boundary_source
), merged AS (
    SELECT code, ST_UnaryUnion(ST_Collect(geom)) AS geom
    FROM parsed
    GROUP BY code
), validated AS (
    SELECT code, geom
    FROM merged
    WHERE ST_IsValid(geom)
      AND GeometryType(geom) = 'POLYGON'
      AND ST_Area(geom::geography) > 1000000
)
UPDATE districts d
SET boundary = v.geom::geography,
    center_lat = ST_Y(ST_PointOnSurface(v.geom)),
    center_lng = ST_X(ST_PointOnSurface(v.geom))
FROM validated v
WHERE d.code = v.code;

DO $$
DECLARE
    updated_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO updated_count
    FROM districts d
    JOIN (SELECT DISTINCT code FROM _legacy_district_boundary_source) s USING (code)
    WHERE d.boundary IS NOT NULL
      AND ST_IsValid(d.boundary::geometry)
      AND ST_Area(d.boundary) > 1000000
      AND ST_Covers(d.boundary, ST_SetSRID(ST_MakePoint(d.center_lng, d.center_lat), 4326)::geography);
    IF updated_count <> 22 THEN
        RAISE EXCEPTION 'legacy district boundary validation failed: %/22', updated_count;
    END IF;
END $$;

COMMIT;
